import argparse
import collections
import os
import sys


def log_filter(data):
    errors, warnings, infos = [], [], 0
    for line in data.splitlines():
        low = line.lower()
        if any(s in low for s in ('error', 'fatal')):
            errors.append(line)
        elif any(s in low for s in ('warn', 'deprecated')):
            warnings.append(line)
        elif 'info' in low:
            infos += 1
    ec, wc = collections.Counter(errors), collections.Counter(warnings)
    out = ['Log Summary', f'   [error] {len(errors)} errors ({len(ec)} unique)',
           f'   [warn] {len(warnings)} warnings ({len(wc)} unique)',
           f'   [info] {infos} info messages', '']
    if errors:
        out.append('[ERRORS]')
        for line, n in ec.items():
            out.append(f'   [×{n}] {line}' if n > 1 else f'   {line}')
        out.append('')
    if warnings:
        out.append('[WARNINGS]')
        for line, n in wc.items():
            out.append(f'   [×{n}] {line}' if n > 1 else f'   {line}')
        out.append('')
    return '\n'.join(out).rstrip() + '\n'


def main():
    args = sys.argv[1:]
    if args and args[0] == 'log':
        parser = argparse.ArgumentParser(prog='executable log', add_help=True)
        parser.add_argument('file', nargs='?')
        parser.add_argument('-v', action='count', default=0)
        parser.add_argument('--ultra-compact', action='store_true')
        ns = parser.parse_args(args[1:])
        try:
            data = open(ns.file, encoding='utf-8', errors='replace').read() if ns.file else sys.stdin.read()
        except OSError as e:
            print(f'rtk: {e.strerror} (os error {e.errno})', file=sys.stderr)
            return 1
        sys.stdout.write(log_filter(data))
        return 0
    if args and args[0] in ('-V', '--version'):
        print('rtk 0.28.2')
        return 0
    print('Usage: executable <COMMAND>', file=sys.stderr)
    return 2


if __name__ == '__main__':
    raise SystemExit(main())

