        out.append('[WARNINGS]')
        for line, n in wc.items():
            out.append(f'   [×{n}] {line}' if n > 1 else f'   {line}')
        out.append('')
    rendered = '\n'.join(out).rstrip()
    return rendered + ('\n\n' if not warnings else '\n')


