"""Compact dependency summaries for RTK's standalone deps command."""
import json
import os
import sys
import re


def _cargo(path):
    try:
        with open(path, encoding="utf-8") as f:
            raw = f.read()
    except OSError:
        return None
    # Cargo's dependency declarations are simple TOML tables. Parse only the
    # sections we display, keeping Python 3.10 compatibility (no tomllib).
    data = {}
    section = ""
    for line in raw.splitlines():
        m = re.match(r"\s*\[([^]]+)\]\s*(?:#.*)?$", line)
        if m:
            section = m.group(1)
            data.setdefault(section, {})
            continue
        m = re.match(r'\s*([A-Za-z0-9_.-]+)\s*=\s*(.*?)\s*(?:#.*)?$', line)
        if m and section:
            data[section][m.group(1)] = m.group(2).strip()
    lines = ["Rust (Cargo.toml):"]
    for key, label in (("dependencies", "Dependencies"), ("dev-dependencies", "Dev"), ("build-dependencies", "Build")):
        vals = data.get(key, {})
        if not vals:
            continue
        lines.append(f"  {label} ({len(vals)}):")
        for dep, spec in vals.items():
            mt = re.search(r'version\s*=\s*["\']([^"\']+)', spec)
            if not mt:
                mt = re.match(r'["\']([^"\']*)["\']', spec)
            ver = mt.group(1) if mt else spec
            lines.append(f"    {dep} ({ver or '*'})")
    return lines


def _npm(path):
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        return None
    lines = ["Node.js (package.json):"]
    if data.get("name") or data.get("version"):
        lines.append(f"  {data.get('name', '?')} @ {data.get('version', '?')}")
    for key, label in (("dependencies", "Dependencies"), ("devDependencies", "Dev Dependencies")):
        vals = data.get(key, {})
        if isinstance(vals, dict) and vals:
            lines.append(f"  {label} ({len(vals)}):")
            lines.extend(f"    {k}" + (f" ({v})" if v and v != "*" else "") for k, v in vals.items())
    return lines


def _requirements(path):
    try:
        with open(path, encoding="utf-8") as f:
            items = [x.strip() for x in f if x.strip() and not x.lstrip().startswith("#") and not x.lstrip().startswith("-")]
    except OSError:
        return None
    return ["Python (requirements.txt):", f"  Packages ({len(items)}):", *["    " + x for x in items]]


def _pyproject(path):
    try:
        raw = open(path, encoding="utf-8").read()
    except OSError:
        return None
    lines = ["Python (pyproject.toml):"]
    section, items = "", []
    for line in raw.splitlines():
        m = re.match(r"\s*\[([^]]+)\]", line)
        if m:
            section = m.group(1)
        elif "dependencies" in section and "=" in line:
            key, val = line.split("=", 1)
            if key.strip() and not key.strip().startswith("#"):
                val = val.strip()
                if val.endswith('"'):
                    val = val[:-1]
                items.append(f"{key.strip()} = {val}")
    if items:
        lines.extend((f"  Dependencies ({len(items)}):", *["    " + x for x in items]))
    return lines


def _gomod(path):
    try:
        raw = open(path, encoding="utf-8").read()
    except OSError:
        return None
    module, gover, deps, inside = "", "", [], False
    for line in raw.splitlines():
        s = line.strip()
        if s.startswith("module "):
            module = s[7:].strip()
        elif s.startswith("go "):
            gover = s[3:].strip()
        elif s.startswith("require ("):
            inside = True
        elif inside and s == ")":
            inside = False
        elif s.startswith("require "):
            deps.append(s[8:].strip())
        elif inside and s and not s.startswith("//"):
            deps.append(s)
    lines = ["Go (go.mod):"]
    if module:
