            if s.startswith(('#', '//', '/*', '*')):
                continue
            if not s:
                if not blank:
                    result.append('')
                blank = True
            else:
                result.append(line)
                blank = False
        return result
    result, body_indent = [], None
    for line in lines:
        stripped = line.strip()
        indent = len(line) - len(line.lstrip())
        if body_indent is not None:
            if stripped and indent > body_indent:
                if re.match(r'(async\s+)?def\s|class\s|fn\s|function\s|func\s', stripped):
                    result.append('// ... implementation')
                    body_indent = None
                else:
                    continue
            elif not stripped:
                continue
            if body_indent is not None:
                result.append('// ... implementation')
                body_indent = None
        if re.match(r'\s*(def |async def |class |fn |function |func |pub fn |impl\b)', line):
            result.append(line)
            if not stripped.startswith(('class ', 'impl ')):
                body_indent = indent
        elif stripped and not stripped.startswith(('#', '//')):
            result.append(line)
    if body_indent is not None:
        result.append('// ... implementation')
    return result

