def _invoke(args, label):
    try:
        return subprocess.run(['docker'] + args, stdout=subprocess.PIPE,
                              stderr=subprocess.PIPE, text=True, env=os.environ.copy())
    except FileNotFoundError:
        print(f'rtk: Failed to run docker {label}: Failed to execute command: No such file or directory (os error 2)')
        return None


def _fields(line, count):
    parts = line.rstrip('\n').split('\t')
    if len(parts) < count:
        parts += [''] * (count - len(parts))
    return parts[:count]


def _ps(args):
    all_containers = any(x in ('-a', '--all') for x in args)
    fields = ['State', 'ID', 'Names', 'Status', 'Image', 'Ports'] if all_containers else ['ID', 'Names', 'Status', 'Image', 'Ports']
    template = '\t'.join('{{.' + f + '}}' for f in fields)
    cmd = ['ps'] + args + ['--format', template]
    p = _invoke(cmd, ' '.join(args or ['ps']))
    if p is None: return 1
    if p.returncode:
        text = p.stderr.strip() or p.stdout.strip()
        if text: print(text)
        return p.returncode
    rows = [x for x in p.stdout.splitlines() if x.strip()]
    if not all_containers:
        print(f'[docker] {len(rows)} containers:')
        for row in rows:
            ident, name, status, image, ports = _fields(row, 5)
            print(f'  {ident} {name} ({image}) {status} [{ports}]')
        return 0
    running, stopped = [], []
    for row in rows:
        state, ident, name, status, image, ports = _fields(row, 6)
        item = f'  {ident} {name} ({image}) {status}' + (f' [{ports}]' if ports else '')
        (running if state.lower() == 'running' else stopped).append(item)
    print(f'[docker] {len(running)} running:')
    for row in running: print(row)
    print(f'[docker] {len(stopped)} stopped/exited:')
    for row in stopped: print(row)
    return 0


def _images(args):
    p = _invoke(['images'] + args + ['--format', '{{.Repository}}:{{.Tag}}\t{{.Size}}'], 'images')
    if p is None: return 1
    if p.returncode:
        text = p.stderr.strip() or p.stdout.strip()
        if text: print(text)
        return p.returncode
    rows = [_fields(x, 2) for x in p.stdout.splitlines() if x.strip()]
    total_mb = 0.0
    for _, size in rows:
        try:
            number = float(size[:-2])
            unit = size[-2:].lower()
            total_mb += number * (1024 if unit == 'gb' else 1 / 1024 if unit == 'kb' else 1)
        except (ValueError, IndexError):
            pass
    print(f'[docker] {len(rows)} images ({int(total_mb)}MB)')
    for name, size in rows: print(f'  {name} [{size}]')
    return 0


def _compose(args):
    template = '{{.Name}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}'
    p = _invoke(['compose', 'ps'] + args + ['--format', template], 'compose ps')
    if p is None: return 1
    if p.returncode:
        text = p.stderr.strip() or p.stdout.strip()
        if text: print(text)
        return p.returncode
    rows = [_fields(x, 4) for x in p.stdout.splitlines() if x.strip()]
    print(f'[compose] {len(rows)} services:')
    for name, image, status, ports in rows:
        shown_ports = ports.split(',', 1)[0].split(':', 1)[0] if ports else ''
        print(f'  {name} ({image}) {status} [{shown_ports}]')
    return 0


def run(args, log_filter):
    if not args:
        sys.stdout.write(DOCKER_HELP['root']); return 0
    if any(x in ('-h', '--help') for x in args):
        key = 'root'
        if args[0] in ('ps', 'images', 'logs'):
            key = args[0]
        elif args[:2] == ['compose', 'ps']:
            key = 'compose ps'
        elif args[0] == 'compose':
            key = 'compose'
        if key in DOCKER_HELP:
            sys.stdout.write(DOCKER_HELP[key]); return 0
    command, rest = args[0], args[1:]
    if command == 'ps': return _ps(rest)
    if command == 'images': return _images(rest)
    if command == 'compose' and rest and rest[0] == 'ps': return _compose(rest[1:])
    if command == 'logs':
        p = _invoke(args, ' '.join(args))
        if p is None: return 1
        if p.returncode:
            text = p.stderr.strip() or p.stdout.strip()
            if text: print(text)
            return p.returncode
        print(f'[docker] Logs for {rest[0] if rest else "container"}:')
        sys.stdout.write(log_filter(p.stdout))
        return 0
    p = _invoke(args, ' '.join(args))
    if p is None: return 1
    sys.stdout.write(p.stdout)
    if p.stderr: sys.stderr.write(p.stderr)
    return p.returncode

