        summary += f" in {max(1, len(packages))} packages"
        out = [summary]
        for package in sorted({p for p,t in tests if tests[(p,t)]["status"] == "fail"}):
            group = [((p,t), v) for (p,t),v in tests.items() if p == package and v["status"] == "fail"]
            pkg_passed = sum(v["status"] == "pass" for (p,_),v in tests.items() if p == package)
            out.extend(["", f"{package.rsplit('/',1)[-1]} ({pkg_passed} passed, {len(group)} failed)"])
            for (_, test), rec in group:
                out.append(f"  [FAIL] {test}")
                out.extend("  " + x for x in rec["output"] if x.strip())
        return "\n".join(out)
    if n == "go-build":
        errs=[x for x in lines if "error:" in x.lower()]
        if not errs: return "Go build: Success"
        return f"Go build: {len(errs)} errors\n"+"═"*39+"\n"+"\n".join(f"{i}. {x}" for i,x in enumerate(errs,1))
    if n == "tsc":
        parsed = []
        for line in lines:
            m = re.match(r"(.+?)\((\d+),\d+\): error (TS\d+): (.*)", line)
            if m:
                parsed.append((m.group(1), int(m.group(2)), m.group(3), m.group(4)))
        if not parsed:
            return "TypeScript compilation completed"
        grouped = defaultdict(list)
        codes = Counter()
        for item in parsed:
            grouped[item[0]].append(item[1:])
            codes[item[2]] += 1
        out = [f"TypeScript: {len(parsed)} errors in {len(grouped)} files", "═"*39,
               "Top codes: " + ", ".join(f"{c} ({n}x)" for c,n in codes.most_common(5)), ""]
        for filename in sorted(grouped):
            errs = grouped[filename]
            out.append(f"{filename} ({len(errs)} errors)")
            out.extend(f"  L{line_no}: {code} {message}" for line_no,code,message in errs)
            out.append("")
        return "\n".join(out).rstrip()
    if n == "prettier":
        files=[x.strip() for x in lines if x.strip() and ("[warn]" in x or "Code style issues" in x)]
        return "Prettier: All files formatted correctly" if not files else "Prettier: " + str(len(files)) + " files need formatting\n" + "\n".join(files)
    if n == "mypy":
        parsed = []
        for line in lines:
            m = re.match(r"(.+?):(\d+): error: (.*)", line)
            if m:
                body = m.group(3)
                code = re.search(r"\[([^]]+)\]$", body)
                parsed.append((m.group(1), int(m.group(2)), code.group(1) if code else "", body[:code.start()].rstrip() if code else body))
        if not parsed:
            return "mypy: No issues found"
        grouped = defaultdict(list)
        for filename, line_no, code, message in parsed:
            grouped[filename].append((line_no, code, message))
        out = [f"mypy: {len(parsed)} errors in {len(grouped)} files", "═"*39]
        for filename in sorted(grouped):
            errs = grouped[filename]
            out.append(f"{filename} ({len(errs)} errors)")
            for line_no, code, message in errs:
                out.append(f"  L{line_no}: " + (f"[{code}] " if code else "") + message)
        return "\n".join(out)
    if n == "ruff-check":
        try:
            records = json.loads(text)
            if not isinstance(records, list):
                raise TypeError("expected sequence")
        except Exception as exc:
            if not text.strip():
                problem = "EOF while parsing a value at line 1 column 0"
            elif isinstance(exc, TypeError):
                problem = "invalid type: map, expected a sequence at line 1 column 0"
            elif text.lstrip().startswith("{"):
                problem = "invalid type: map, expected a sequence at line 1 column 0"
            else:
                problem = f"expected value at line 1 column 1"
            return f"Ruff check (JSON parse failed: {problem})\n" + text
        issues = [x for x in records if isinstance(x, dict)]
        if not issues:
            return "Ruff: No issues found"
        rules, files = Counter(), defaultdict(list)
        for issue in issues:
            code = str(issue.get("code") or "unknown")
            filename = str(issue.get("filename") or "<unknown>")
            loc = issue.get("location") or {}
            row, col = loc.get("row", 0), loc.get("column", 0)
            msg = str(issue.get("message") or "")
            rules[code] += 1
            files[filename].append((code, row, col, msg))
        out = [f"Ruff: {len(issues)} issues in {len(files)} files", "═"*39, "Top rules:"]
        out.extend(f"  {name} ({count}x)" for name,count in rules.most_common(5))
        out.append("")
        out.append("Top files:")
        for filename, entries in sorted(files.items(), key=lambda x: -len(x[1]))[:5]:
            out.append(f"  {filename} ({len(entries)} issues)")
            counts = Counter(x[0] for x in entries)
            out.extend(f"    {code} ({count})" for code,count in counts.items())
        out.extend(["", "Violations:"])
        for filename, entries in files.items():
            out.extend(f"  {filename}:{row}:{col} {code} {msg}" for code,row,col,msg in entries)
        return "\n".join(out)
    if n == "log":
        errors = [x for x in lines if any(s in x.lower() for s in ("error", "fatal", "critical", "panic"))]
        warns = [x for x in lines if any(s in x.lower() for s in ("warn", "notice"))]
        infos = sum("info" in x.lower() for x in lines)
        ec, wc = Counter(errors), Counter(warns)
        out = ["Log Summary", f"   [error] {len(errors)} errors ({len(ec)} unique)",
               f"   [warn] {len(warns)} warnings ({len(wc)} unique)", f"   [info] {infos} info messages", ""]
        if errors:
            out.append("[ERRORS]")
            out.extend(f"   [×{n}] {line}" if n > 1 else f"   {line}" for line, n in ec.items())
            out.append("")
        if warns:
            out.append("[WARNINGS]")
            out.extend(f"   [×{n}] {line}" if n > 1 else f"   {line}" for line, n in wc.items())
            out.append("")
        rendered = "\n".join(out).rstrip()
        return rendered + ("" if warns else "\n")
    return text

    if not args:
        print(SHORT_HELP, file=sys.stderr)
        return 2
    if args in (['--help'], ['-h'], ['help']):
        sys.stdout.write(SHORT_HELP + '\n' if args == ['-h'] else TOP_HELP)
        return 0
    if args and args[0] == 'pipe':
        parser = argparse.ArgumentParser(prog='executable pipe', add_help=True)
        parser.add_argument('-f', '--filter')
        parser.add_argument('--passthrough', action='store_true')
        parser.add_argument('-v', action='count', default=0)
        parser.add_argument('--ultra-compact', action='store_true')
        parser.add_argument('--skip-env', action='store_true')
        ns = parser.parse_args(args[1:])
        data = sys.stdin.read()
        if ns.passthrough or not ns.filter:
            sys.stdout.write(data)
            return 0
        if ns.filter not in pipe_filters.FILTERS:
            print(f"rtk: Unknown filter '{ns.filter}'. Available: " + ', '.join(pipe_filters.FILTERS), file=sys.stderr)
            return 1
        output = pipe_filters.process(ns.filter, data, ns.ultra_compact)
        if output:
            sys.stdout.write(output)
            if not output.endswith('\n') and ns.filter not in ('cargo-test', 'go-test', 'tsc', 'mypy', 'ruff-check', 'log'):
                sys.stdout.write('\n')
        return 0
    if args and args[0] == 'rewrite':
        rest = args[1:]
        if any(x in ('-h', '--help') for x in rest):
            print('''Rewrite a raw command to its RTK equivalent (single source of truth for hooks)

Exits 0 and prints the rewritten command if supported. Exits 1 with no output if the command has no RTK equivalent.

Usage: executable rewrite [OPTIONS] [ARGS...]

Arguments:
  [ARGS...]  Raw command to rewrite (e.g. "git status", "cargo test && git push")

Options:
  -v, --verbose...          Verbosity level (-v, -vv, -vvv)
      --ultra-compact       Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)
      --skip-env            Set SKIP_ENV_VALIDATION=1 for child processes
  -h, --help                Print help''')
            return 0
        rest = [x for x in rest if x not in ('-v', '-vv', '-vvv', '--ultra-compact', '--skip-env')]
        code, rewritten = rewrite_cmd.rewrite(rest)
        if rewritten.startswith('[rtk]'):
            print(rewritten, file=sys.stderr)
        elif rewritten:
            sys.stdout.write(rewritten)
        return code
    if args and args[0] == 'git':
        return git_cmd.handle(args[1:])
    if args and args[0] == 'cargo':
