"""Command rewrite rules exposed by ``rtk rewrite``."""
import re
import shlex


ROOT_MAP = {
    "ls": "ls", "tree": "tree", "find": "find", "fd": "find",
    "rg": "grep", "grep": "grep", "git": "git", "gh": "gh",
    "glab": "glab", "aws": "aws", "psql": "psql", "pnpm": "pnpm",
    "cargo": "cargo", "pytest": "pytest", "jest": "jest", "vitest": "vitest",
    "tsc": "tsc", "eslint": "lint", "biome": "lint", "prettier": "prettier",
    "playwright": "playwright", "prisma": "prisma", "ruff": "ruff", "mypy": "mypy",
    "pip": "pip", "go": "go", "docker": "docker", "kubectl": "kubectl",
    "curl": "curl", "wget": "wget", "dotnet": "dotnet", "npm": "npm",
    "golangci-lint": "golangci-lint", "gradlew": "gradlew", "gt": "gt",
    "make": "make", "ruby": "ruby", "rake": "rake", "rspec": "rspec",
    "rubocop": "rubocop", "bundle": "bundle", "npx": "npx",
}


def _map_words(words):
    if not words:
        return None
    # Do not rewrite an already-prefixed command. The hook leaves it intact.
    if words[0] == "rtk":
        return " ".join(words)
    if words[0] in ("command", "sudo", "env") and len(words) > 1:
        inner = _map_words(words[1:])
        return words[0] + " " + inner if inner else None
    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", words[0]) and len(words) > 1:
        if words[0].startswith("RTK_DISABLED="):
            return "[rtk] RTK_DISABLED=1 detected — skipping filter for this command. Remove RTK_DISABLED=1 to restore token savings."
        inner = _map_words(words[1:])
        return words[0] + " " + inner if inner else None
    cmd = words[0]
    if cmd == "cat":
        if len(words) < 2:
            return None
        return "rtk read " + " ".join(words[1:])
    if cmd == "head":
        if len(words) < 2:
            return None
        m = re.fullmatch(r"-(\d+)", words[1])
        if not m or len(words) < 3:
            return None
        return "rtk read " + " ".join(words[2:]) + " --max-lines " + m.group(1)
    if cmd == "tail":
        if len(words) < 2:
            return None
        m = re.fullmatch(r"-(\d+)", words[1])
        if not m or len(words) < 3:
            return None
        return "rtk read " + " ".join(words[2:]) + " --tail-lines " + m.group(1)
    if cmd == "python" or cmd == "python3":
        if len(words) >= 3 and words[1:3] == ["-m", "pytest"]:
            extra = " ".join(words[3:])
            return "rtk pytest" + (" " + extra if extra else "")
        return None
    args = words[1:]
    if cmd == "npx" and args:
        target = {"tsc": "tsc", "eslint": "lint", "biome": "lint", "prisma": "prisma",
                  "prettier": "prettier", "playwright": "playwright", "vitest": "vitest", "jest": "jest"}.get(args[0])
        if target:
            extra = args[1:]
            if args[0] == "vitest" and extra and extra[0] == "run":
                extra = extra[1:]
            return "rtk " + target + (" " + " ".join(extra) if extra else "")
    if cmd not in ROOT_MAP:
        return None
    target = ROOT_MAP[cmd]
    if cmd == "npm" and (not args or args[0] not in ("run", "exec")):
        return None
    if cmd == "pnpm" and (not args or args[0] not in ("list", "outdated", "install", "add", "remove", "run", "exec", "test", "build")):
        return None
    if cmd == "pip" and (not args or args[0] not in ("list", "outdated", "install", "show", "freeze")):
        return None
    if cmd == "go" and (not args or args[0] not in ("test", "build", "vet")):
        return None
    if cmd == "gt" and not args:
        return None
    if cmd == "docker" and not args:
        return None
    if cmd == "kubectl" and not args:
        return None
    if cmd == "git" and (not args or args[0] not in ("status", "diff", "log", "add", "commit", "push", "pull", "show", "branch", "fetch", "stash")):
        return None
    return "rtk " + target + (" " + " ".join(args) if args else "")


def _split_shell(text, controls):
    parts, start, quote, escape, i = [], 0, None, False, 0
    while i < len(text):
        c = text[i]
        if escape:
            escape = False
        elif c == "\\" and quote != "'":
            escape = True
        elif quote:
            if c == quote:
                quote = None
        elif c in ("'", '"'):
            quote = c
        else:
            token = next((x for x in controls if text.startswith(x, i)), None)
            if token:
                parts.extend((text[start:i], token))
                i += len(token)
                start = i
                continue
        i += 1
    parts.append(text[start:])
    return parts


def rewrite(argv):
    """Return (exit code, rewritten command text) for argument strings."""
    raw = " ".join(argv).strip()
    if not raw:
        return 1, ""
    # Compound command separators are retained, and each independent command
    # is rewritten. Pipes only rewrite their initial command, as shell hooks do.
    chunks = _split_shell(raw, ("&&", "||", ";"))
    output = []
    any_rewritten = False
    for chunk in chunks:
        if not chunk:
            output.append(chunk)
            continue
        if chunk in ("&&", "||", ";"):
            output.append(f" {chunk} ")
            continue
        chunk = chunk.strip()
        pipeparts = _split_shell(chunk, ("|",))
        try:
            words = shlex.split(pipeparts[0], posix=False)
        except ValueError:
            return 1, ""
        if words and re.fullmatch(r"RTK_DISABLED=.*", words[0]):
            return 1, "[rtk] RTK_DISABLED=1 detected — skipping filter for this command. Remove RTK_DISABLED=1 to restore token savings."
        mapped = _map_words(words)
        if mapped is None:
            output.append(chunk)
        else:
            output.append(mapped + (" |" + "|".join(pipeparts[1:]) if len(pipeparts) > 1 else ""))
            any_rewritten = True
    return (3, "".join(output)) if any_rewritten else (1, "")
